                  li x29, 0x8ffffffc
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x0
                  sw x10, 0(x29)
                  j main
test_done:        
                  li x29, 0x8ffffff8
                  li x10, 0x0
                  slli x10, x10, 8
                  addi x10, x10, 0x1
                  sw x10, 0(x29)
                  ecall

